import 'dart:async';
import 'dart:io';

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:record/record.dart';
import 'package:papigiras_app/voice/local_voice_recorder.dart';
import 'package:papigiras_app/voice/voice_note_draft.dart';

// Replaces the native platform entirely: these samples are generated bytes,
// never microphone input and never permission requests to the host OS.
class _SyntheticRecordPlatform extends RecordPlatform {
  StreamController<Uint8List>? samples;
  int stops = 0, cancels = 0;
  RecordConfig? config;
  @override
  Future<void> create(String id) async {}
  @override
  Future<bool> hasPermission(String id, {bool request = true}) async => true;
  @override
  Stream<RecordState> onStateChanged(String id) => const Stream.empty();
  @override
  Future<Stream<Uint8List>> startStream(String id, RecordConfig value) async {
    config = value;
    samples = StreamController<Uint8List>();
    return samples!.stream;
  }

  @override
  Future<String?> stop(String id) async {
    stops++;
    await samples?.close();
    return null;
  }

  @override
  Future<void> cancel(String id) async {
    cancels++;
    if (samples != null && !samples!.isClosed) await samples!.close();
  }

  @override
  Future<void> dispose(String id) async {}
  @override
  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  late Directory cache;
  late RecordPlatform original;
  late _SyntheticRecordPlatform native;
  late LocalVoiceRecorder recorder;
  const paths = MethodChannel('plugins.flutter.io/path_provider');
  setUp(() async {
    cache = await Directory.systemTemp.createTemp('papigiras-recorder-test-');
    original = RecordPlatform.instance;
    native = _SyntheticRecordPlatform();
    RecordPlatform.instance = native;
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(paths, (call) async {
          if (call.method == 'getTemporaryDirectory') return cache.path;
          throw StateError('Unexpected filesystem operation');
        });
    recorder = LocalVoiceRecorder();
  });
  tearDown(() async {
    await recorder.dispose();
    RecordPlatform.instance = original;
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(paths, null);
    if (await cache.exists()) await cache.delete(recursive: true);
  });

  test(
    'saves a canonical WAV under a fresh cache directory and transfers ownership',
    () async {
      expect(await recorder.requestPermission(), isTrue);
      await recorder.start(onLimitReached: () {}, onInterrupted: () {});
      native.samples!.add(Uint8List(32000));
      await Future<void>.delayed(Duration.zero);
      final draft = (await recorder.stop())!;
      final file = File(draft.file.path);
      expect(file.parent.parent.path, cache.path);
      expect(
        file.parent.path.split(Platform.pathSeparator).last,
        startsWith('papigiras-voice-'),
      );
      expect(await file.exists(), isTrue);
      expect(await file.length(), 32044);
      expect(draft.duration, const Duration(seconds: 1));
      expect(draft.byteLength, 32044);
      expect(native.config!.encoder, AudioEncoder.pcm16bits);
      expect(native.config!.sampleRate, 16000);
      expect(native.config!.numChannels, 1);
      await recorder.dispose();
      expect(
        await file.exists(),
        isTrue,
        reason: 'The composing form owns the returned draft.',
      );
      await recorder.discard(draft);
      expect(await file.parent.exists(), isFalse);
    },
  );

  test(
    'simultaneous cap and manual stop finalize only once with at most 60 seconds',
    () async {
      Future<VoiceNoteDraft?>? limitResult;
      await recorder.start(
        onLimitReached: () => limitResult = recorder.stop(),
        onInterrupted: () {},
      );
      native.samples!.add(Uint8List(1920000 + 1001));
      await Future<void>.delayed(Duration.zero);
      final manual = await recorder.stop();
      final capped = await limitResult;
      expect(capped, isNotNull);
      if (manual != null) expect(identical(manual, capped), isTrue);
      expect(native.stops, 1);
      expect(capped!.duration, const Duration(seconds: 60));
      expect(await File(capped.file.path).length(), 1920000 + 44);
      await recorder.discard(capped);
      expect(await cache.list().isEmpty, isTrue);
    },
  );
}
